#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>
#include <Eigen/Dense>
#include <sstream>
#include <string>

// Define M_PI if not available
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

// Forward declarations
void ktrmem(int flag);
void sma1b(const Eigen::Matrix<double, 3, 3>& kij, int grid_id, int npvt, int ifkgg, double temp);

// Dummy CommonData removed — not needed for clean Gauss path

// Helper function to get DEGRA (degrees to radians conversion factor)
double get_degra() {
    return M_PI / 180.0;
}

// Main CQUAD4 stiffness computation function — CLEAN GAUSS ONLY
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness(
    const std::vector<std::vector<double>>& nodes,
    double e, double nu, double t) {

    // Nodes: 4 corners in order: (x0,y0), (x1,y1), (x2,y2), (x3,y3)
    // Assume planar, z=0
    std::vector<double> x = {nodes[0][0], nodes[1][0], nodes[2][0], nodes[3][0]};
    std::vector<double> y = {nodes[0][1], nodes[1][1], nodes[2][1], nodes[3][1]};

    // Material matrix D for plane stress
    double d11 = e / (1.0 - nu*nu);
    double d12 = d11 * nu;
    double d22 = d11;
    double d66 = e / (2.0 * (1.0 + nu));

    Eigen::Matrix<double, 3, 3> d;
    d << d11, d12, 0.0,
         d12, d22, 0.0,
         0.0, 0.0, d66;

    // Gauss points for 2x2 integration
    std::vector<double> xi = {-1.0/std::sqrt(3.0), 1.0/std::sqrt(3.0)};
    std::vector<double> eta = {-1.0/std::sqrt(3.0), 1.0/std::sqrt(3.0)};

    // Shape functions and derivatives
    auto shape_func = [&](double r, double s) -> std::vector<double> {
        return {
            0.25*(1-r)*(1-s),
            0.25*(1+r)*(1-s),
            0.25*(1+r)*(1+s),
            0.25*(1-r)*(1+s)
        };
    };

    auto dNdr = [&](double r, double s) -> std::vector<double> {
        return {
            -0.25*(1-s),
            0.25*(1-s),
            0.25*(1+s),
            -0.25*(1+s)
        };
    };

    auto dNds = [&](double r, double s) -> std::vector<double> {
        return {
            -0.25*(1-r),
            -0.25*(1+r),
            0.25*(1+r),
            0.25*(1-r)
        };
    };

    // Jacobian computation
    auto jacobian = [&](double r, double s) -> Eigen::Matrix2d {
        std::vector<double> dn_dr = dNdr(r, s);
        std::vector<double> dn_ds = dNds(r, s);

        double dx_dr = 0.0, dy_dr = 0.0, dx_ds = 0.0, dy_ds = 0.0;
        for (int i = 0; i < 4; ++i) {
            dx_dr += dn_dr[i] * x[i];
            dy_dr += dn_dr[i] * y[i];
            dx_ds += dn_ds[i] * x[i];
            dy_ds += dn_ds[i] * y[i];
        }

        Eigen::Matrix2d jac;
        jac << dx_dr, dx_ds,
               dy_dr, dy_ds;
        return jac;
    };

    // Strain-displacement matrix B (3x8)
    auto compute_b = [&](double r, double s) -> Eigen::Matrix<double, 3, 8> {
        Eigen::Matrix2d jac = jacobian(r, s);
        double det_jac = jac.determinant();
        if (std::abs(det_jac) < 1e-15) {
            return Eigen::Matrix<double, 3, 8>::Zero();
        }
        // Compute inverse via LU for stability
        Eigen::Matrix2d jac_inv = jac.inverse();

        std::vector<double> dn_dr = dNdr(r, s);
        std::vector<double> dn_ds = dNds(r, s);

        Eigen::Matrix<double, 3, 8> b = Eigen::Matrix<double, 3, 8>::Zero();

        for (int i = 0; i < 4; ++i) {
            double dn_dx = jac_inv(0,0)*dn_dr[i] + jac_inv(0,1)*dn_ds[i];
            double dn_dy = jac_inv(1,0)*dn_dr[i] + jac_inv(1,1)*dn_ds[i];

            b(0, 2*i) = dn_dx;      // εxx: dN_i/dx for u_i
            b(1, 2*i+1) = dn_dy;   // εyy: dN_i/dy for v_i
            b(2, 2*i) = dn_dy;     // γxy: dN_i/dy for u_i
            b(2, 2*i+1) = dn_dx;   // γxy: dN_i/dx for v_i
        }

        return b;
    };

    // Integrate stiffness matrix: K = ∫ B^T D B |J| dr ds
    Eigen::Matrix<double, 8, 8> k_global = Eigen::Matrix<double, 8, 8>::Zero();
    double w = 1.0; // 2x2 Gauss weight = 1.0

    for (double r : xi) {
        for (double s : eta) {
            Eigen::Matrix<double, 3, 8> b = compute_b(r, s);
            double det_jac = jacobian(r, s).determinant();
            if (std::abs(det_jac) < 1e-15) continue;

            Eigen::Matrix<double, 8, 8> k_local = t * b.transpose() * d * b * std::abs(det_jac);
            k_global += k_local;
        }
    }

    return k_global;
}

int main() {
    // Test case: Nodes (0,0), (2,0), (2,1.5), (0,1.5) — counter-clockwise
    std::vector<std::vector<double>> nodes = {
        {0.0, 0.0},
        {2.0, 0.0},
        {2.0, 1.5},
        {0.0, 1.5}
    };

    double e = 200e9;      // Pa (steel)
    double nu = 0.3;       // Poisson's ratio
    double t = 0.01;       // m (10 mm)

    // Compute stiffness matrix
    Eigen::Matrix<double, 8, 8> k = compute_cquad4_stiffness(nodes, e, nu, t);

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";

    for (int i = 0; i < 8; ++i) {
        if (i > 0) std::cout << ",";
        std::cout << "[";
        for (int j = 0; j < 8; ++j) {
            if (j > 0) std::cout << ",";
            std::cout << std::scientific << std::setprecision(15) << k(i,j);
        }
        std::cout << "]";
    }

    std::cout << "]}" << std::endl;

    return 0;
}
